// Fecha mínima de análisis.
// Todos los bloques solo consideran registros posteriores a esta fecha.
VAR _Fecha = DATE ( 2024, 1, 1 )

/////////////////////////////////////////////////////////////////////////////////////////
// _A_Base
// Extrae las relaciones audiencia-juez válidas y les agrega información auxiliar
// proveniente de las tablas relacionadas (audiencia, tribunal, expediente, etc.).
// Se utiliza CALCULATETABLE para empujar los filtros al Storage Engine y
// ADDCOLUMNS para evitar múltiples RELATED() repetidos posteriormente.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _A_Base =
    ADDCOLUMNS (
        CALCULATETABLE (
            vwSGJRelAudienciaJuecesBO,
            vwSGJRelAudienciaJuecesBO[Idusuario] <> BLANK (),
            vwSGJRelAudienciaJuecesBO[Idusuario] <> 999999,
            vwSGJAudienciasBO[FechaAudiencia] >= _Fecha,
            vwSGJAudienciasBO[Estatus] = "Transcurrida"
        ),
        "@IdGeneral", RELATED ( vwSGJAudienciasBO[idaudiencia] ),
        "@Fecha", RELATED ( vwSGJAudienciasBO[FechaAudiencia] ),
        "@CodForm", RELATED ( vwSGJEntradaExpedientesBO[Cod_Formulario] ),
        "@Cod_Tribunal", RELATED ( dvwSalasBO[CodEstadisticas] ),
        "@Sala", RELATED ( vwSGJEntradaExpedientesBO[IdSala3] ),
        "@Num_Exped", RELATED ( vwSGJEntradaExpedientesBO[NumeroTramite] )
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _A
// Estandariza las audiencias al formato común utilizado por el UNION final.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _A =
    SELECTCOLUMNS (
        _A_Base,
        "IdGeneral", [@IdGeneral],
        "Fecha", [@Fecha],
        "CodForm", [@CodForm],
        "idpuntuacion", [@CodForm] & "-5",
        "Cod_Tribunal", [@Cod_Tribunal],
        "Sala", [@Sala],
        "Num_Exped", [@Num_Exped],
        "CodJuez", vwSGJRelAudienciaJuecesBO[Idusuario],
        "Num_Sentencia_o_Resolucion",
            "Audiencia d/f " & [@Fecha],
        "Tipo", "Audiencia"
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _Asignados_Base
// Obtiene expedientes asignados válidos y agrega columnas auxiliares relacionadas
// (NUC y tribunal) para evitar recalcular RELATED() múltiples veces.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _Asignados_Base =
    ADDCOLUMNS (
        CALCULATETABLE (
            vwSGJEntradaExpedientesBO,
            vwSGJEntradaExpedientesBO[FechaAsignacionEstimada] >= _Fecha,
            vwSGJEntradaExpedientesBO[idJuez] <> BLANK (),
            vwSGJEntradaExpedientesBO[idJuez] <> 999999,
            vwSGJEntradaExpedientesBO[Incluir] = 1,
            'Tipo Asunto'[cod_grupo_tipo_asunto_entrada] <> 3
        ),
        "@NUC", RELATED ( vwSGJCasos[NUC] ),
        "@Cod_Tribunal", RELATED ( dvwSalasBO[IdTribunal] )
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _Asignados
// Estandariza los expedientes asignados al formato común utilizado por el UNION.
// También construye el texto descriptivo del expediente y estado actual.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _Asignados =
    SELECTCOLUMNS (
        _Asignados_Base,
        "IdGeneral", vwSGJEntradaExpedientesBO[IdTramite],
        "Fecha", vwSGJEntradaExpedientesBO[FechaAsignacionEstimada],
        "CodForm", vwSGJEntradaExpedientesBO[Cod_Formulario],
        "idpuntuacion", vwSGJEntradaExpedientesBO[Idpuntuacion],
        "Cod_Tribunal", [@Cod_Tribunal],
        "Sala", vwSGJEntradaExpedientesBO[IdSala3],
        "Num_Exped",
            COALESCE (
                [@NUC],
                "S/N D/F " & vwSGJEntradaExpedientesBO[AsignacionJuez]
            )
                & IF (
                    ISBLANK ( vwSGJEntradaExpedientesBO[FechaSalida] ),
                    " (Pendiente)",
                    " (Salida " & vwSGJEntradaExpedientesBO[FechaSalida] & ")"
                )
                & " // Ult. Aud. "
                & IF (
                    ISBLANK ( vwSGJEntradaExpedientesBO[UltimaAudiencia] ),
                    "No registrada",
                    "d/f " & vwSGJEntradaExpedientesBO[UltimaAudiencia]
                ),
        "CodJuez", vwSGJEntradaExpedientesBO[idJuez],
        "Num_Sentencia_o_Resolucion", BLANK (),
        "Tipo", "Asignado"
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _DecididosEnlazados_Base
// Obtiene expedientes decididos/enlazados y agrega columnas auxiliares relacionadas
// para reutilización posterior.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _DecididosEnlazados_Base =
    ADDCOLUMNS (
        CALCULATETABLE (
            vwSGJEntradaExpedientesBO,
            vwSGJEntradaExpedientesBO[idJuez] <> BLANK (),
            vwSGJEntradaExpedientesBO[idJuez] <> 999999,
            vwSGJEntradaExpedientesBO[FechaSalida] >= _Fecha,
            NOT ISBLANK( ProductoSalida[FechaFirma] )
        ),
        "@NUC", RELATED ( vwSGJCasos[NUC] ),
        "@Cod_Tribunal", RELATED ( dvwSalasBO[IdTribunal] )
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _DecididosEnlazados
// Estandariza los expedientes decididos enlazados y construye el identificador
// descriptivo del documento/salida.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _DecididosEnlazados =
    SELECTCOLUMNS (
        _DecididosEnlazados_Base,
        "IdGeneral", vwSGJEntradaExpedientesBO[IdDocumentoSalida],
        "Fecha", vwSGJEntradaExpedientesBO[FechaSalida],
        "CodForm", vwSGJEntradaExpedientesBO[Cod_Formulario],
        "idpuntuacion", vwSGJEntradaExpedientesBO[Idpuntuacion],
        "Cod_Tribunal", [@Cod_Tribunal],
        "Sala", vwSGJEntradaExpedientesBO[IdSala3],
        "Num_Exped", [@NUC],
        "CodJuez", vwSGJEntradaExpedientesBO[idJuez],
        "Num_Sentencia_o_Resolucion",
            COALESCE (
                vwSGJEntradaExpedientesBO[IdDocumentoSalida],
                "S/N D/F " & vwSGJEntradaExpedientesBO[FechaSalida]
            )
                & " (Exp. "
                & [@NUC]
                & ")",
        "Tipo", "Decidido"
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _DecididosNoEnlazados
// Obtiene productos de salida no enlazados y los transforma al mismo formato
// estructural utilizado por el resto de bloques.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _DecididosNoEnlazados =
    SELECTCOLUMNS (
        ADDCOLUMNS (
            CALCULATETABLE (
                ProductoSalida,
                ProductoSalida[IdUsuarioDelActor] <> BLANK (),
                ProductoSalida[IdUsuarioDelActor] <> 999999,
                ProductoSalida[FechaSalida] >= _Fecha,
                NOT ISBLANK( ProductoSalida[FechaFirma] ),
                ProductoSalida[Enlazado] = 0,
                ProductoSalida[Duplicado] IN { 2, 3 }
            ),
            "@idpuntuacion",
                ProductoSalida[Cod_formulario]
                    & "-"
                    & IF (
                        ProductoSalida[Formulario]
                            IN { 153, 154, 155, 166 },
                        2,
                        1
                    ),
            "@Num_Sentencia_o_Resolucion",
                COALESCE (
                    ProductoSalida[NumeroDocumento],
                    "S/N D/F " & ProductoSalida[FechaSalida]
                ) & ")"
        ),
        "IdGeneral", ProductoSalida[IdExpediente],
        "Fecha", ProductoSalida[FechaSalida],
        "CodForm", ProductoSalida[Cod_formulario],
        "idpuntuacion", [@idpuntuacion],
        "Cod_Tribunal", ProductoSalida[IdTribunal2],
        "Sala", ProductoSalida[IdSala3],
        "Num_Exped", "No Enlazado",
        "CodJuez", ProductoSalida[IdUsuarioDelActor],
        "Num_Sentencia_o_Resolucion", [@Num_Sentencia_o_Resolucion],
        "Tipo", "Decidido"
    )

/////////////////////////////////////////////////////////////////////////////////////////
// _Base
// Une todas las fuentes homogéneas en una sola tabla virtual.
/////////////////////////////////////////////////////////////////////////////////////////

VAR _Base =
    UNION (
        _Asignados,
        _DecididosEnlazados,
        _DecididosNoEnlazados,
        _A
    )

/////////////////////////////////////////////////////////////////////////////////////////
// RETURN
// Agrega una clasificación agrupada derivada del tipo principal del registro.
/////////////////////////////////////////////////////////////////////////////////////////

RETURN
ADDCOLUMNS (
    _Base,
    "TipoAgr",
        SWITCH (
            TRUE (),
            [Tipo] = "Audiencia",
                "Audiencia",
            [Tipo] = "Asignado"
                && CONTAINSSTRING ( [Num_Exped], "Inactivo" ),
                "Inactivo",
            [Tipo] = "Asignado",
                "Asignado",
            "Decidido"
        )
)
